19	export type PtyKind = 'agent' | 'shell' | 'tui' | 'service';
20	
21	interface PtyRecord {
22	  proc: any; // IPty from node-pty
23	  cwd: string;
24	  isDirectSpawn: boolean;
25	  owner: WebContents | null;
26	  kind: PtyKind;
27	  taskId: string | null;
28	  featureId: string | null;
29	  /**
30	   * Headless xterm mirror fed every output chunk (the VS Code pty-host
31	   * pattern). Serialized on reattach so a fresh renderer xterm shows the
32	   * full terminal state — including output emitted while no renderer was
33	   * attached. Persisted to the snapshot files on kill/exit/quit.
34	   */
35	  mirror: TerminalMirror | null;
36	}
37	
38	const ptys = new Map<string, PtyRecord>();
39	
40	/** Persist a mirror's state to the snapshot files (sync — quit-safe). */
41	function persistMirrorSync(id: string, mirror: TerminalMirror): void {
42	  try {
43	    const data = mirror.serializeNow();
44	    if (!data) return;
45	    const { cols, rows } = mirror.dims();
46	    terminalSnapshotService
47	      .saveSnapshot(id, {
48	        version: 1,
49	        createdAt: new Date().toISOString(),
50	        cols,
51	        rows,
52	        data,
53	      })
54	      .catch(() => {
55	        // Persistence is best-effort (also: no `app` under test env).
56	      });
57	  } catch {
58	    // Persistence is best-effort.
59	  }
60	}
61	
62	/** Detach, persist, and dispose a record's mirror (kill/exit paths). */
63	function persistAndDisposeMirror(id: string, record: PtyRecord): void {
64	  const mirror = record.mirror;
65	  record.mirror = null;
66	  if (!mirror) return;
67	  // TUI tabs never restore from file snapshots (their side-car is torn down
68	  // and re-offered instead) — persisting would only leave orphan files.
69	  if (record.kind !== 'tui') persistMirrorSync(id, mirror);
70	  mirror.dispose();
71	}
72	
73	/** Serialize every live mirror to disk — before-quit + crash-resilience interval. */
74	export function persistAllMirrors(): void {
75	  for (const [id, record] of ptys) {
76	    if (record.kind === 'tui') continue;
77	    if (record.mirror) persistMirrorSync(id, record.mirror);
78	  }
79	}
